import React, { useState, useRef, useEffect, useCallback, useMemo } from "react";
import { SketchPicker } from "react-color";
import { loadFonts } from "../../utils/fontUtils";
import { useProcessMedia } from "../../hooks/useProcessMedia";
import { ASCII_FILTER_DEFINITION } from "../../utils/filterDefinitions";
import startIcon from "../../assets/Icons/start.png";
import { createAppManifest } from "../createAppManifest";
import { createAsciifyIcon } from "../../utils/appIconFactory";
import XpButton from "../../components/XpButton/XpButton";
import styles from "./Asciify.module.css";

export const appManifest = createAppManifest({
  id: "asciify",
  title: "Asciify",
  icon: createAsciifyIcon() || startIcon,
});

export default function Asciify() {
  const canvasRef = useRef(null);
  const fileInputRef = useRef(null);
  const pickerRef = useRef(null);

  const [chars, setChars] = useState(".:-=+*#%@");
  const [fonts, setFonts] = useState(["Arial"]);
  const [font, setFont] = useState("Arial");
  const [density, setDensity] = useState(1);
  const [blockSize, setBlockSize] = useState(16);
  const [fill, setFill] = useState("#000000");
  const [showPicker, setShowPicker] = useState(false);

  const [fileURL, setFileURL] = useState(null);
  const [canExport, setCanExport] = useState(false);

  useEffect(() => {
    loadFonts().then((f) => {
      if (f && f.length) {
        setFonts(f);
        setFont(f[0]);
      } else {
        setFonts(["Arial"]);
        setFont("Arial");
      }
    });
  }, []);

  const defs = useMemo(
    () => ({
      [ASCII_FILTER_DEFINITION.type]: {
        ...ASCII_FILTER_DEFINITION,
        options: ASCII_FILTER_DEFINITION.options.map((opt) =>
          opt.name === "font"
            ? {
                ...opt,
                type: "select",
                options: fonts.length ? fonts : ["Arial"],
                defaultValue: (fonts.length ? fonts : ["Arial"])[0],
              }
            : opt,
        ),
      },
    }),
    [fonts],
  );
  const filters = useMemo(
    () => [
      {
        id: "asciify-main",
        type: ASCII_FILTER_DEFINITION.type,
        enabled: true,
        opts: {
          blockSize,
          density,
          mode: "All",
          low: 0,
          high: 1,
          chars,
          font,
          fillMode: "Color",
          fill,
          textColorMode: "Sampled",
          textColor: "#ffffff",
          overlay: "No",
          alphaThreshold: 0.5,
        },
      },
    ],
    [blockSize, density, chars, font, fill],
  );
  const mediaConfig = useMemo(() => ({ defs, filters }), [defs, filters]);
  const { loadFile, exportResult, mediaError, webgpuSupported } = useProcessMedia(
    canvasRef,
    mediaConfig,
  );

  const handleFileChange = useCallback(
    async (e) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const url = await loadFile(file);
      if (!url) {
        e.target.value = "";
        setCanExport(false);
        return;
      }
      setFileURL(url);
      setCanExport(true);
    },
    [loadFile],
  );

  const handleExport = useCallback(() => {
    if (canExport) exportResult("asciified");
  }, [canExport, exportResult]);

  useEffect(() => {
    const onClick = (e) => {
      if (pickerRef.current?.contains(e.target)) return;
      setShowPicker(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, []);

  return (
    <>
      <div className={styles.formContainer}>
        <div className={styles.formTop}>
          <div className={styles.formLeft}>
            <div className={styles.rainbowTextContainer}>
              {"ASCIIFY :)".split("").map((c, i) => (
                <span
                  key={i}
                  style={{ animationDelay: `${i * 0.1}s, ${i * 0.7}s` }}
                >
                  {c}
                </span>
              ))}
            </div>
            <XpButton
              disabled={!webgpuSupported}
              onClick={() => fileInputRef.current.click()}
            >
              Choose File
            </XpButton>
            <input
              type="file"
              accept="image/*"
              ref={fileInputRef}
              onChange={handleFileChange}
              disabled={!webgpuSupported}
              className={styles.hiddenFileInput}
            />
            {mediaError && (
              <div role="alert" className={styles.formGroup}>
                {mediaError}
              </div>
            )}
          </div>

          <div className={styles.formRight}>
            <XpButton
              onClick={handleExport}
              disabled={!canExport}
            >
              Export
            </XpButton>
          </div>
        </div>

        <div className={styles.formBottom}>
          <div className={styles.formGroup}>
            <label>Characters:</label>
            <input
              type="text"
              value={chars}
              onChange={(e) => setChars(e.target.value)}
            />
          </div>

          <div className={styles.formGroup}>
            <label>Font:</label>
            <select
              value={font}
              onChange={(e) => setFont(e.target.value)}
            >
              {fonts.map((f) => (
                <option key={f} value={f}>
                  {f}
                </option>
              ))}
            </select>
          </div>

          <div className={styles.formGroup}>
            <label>Fill Color:</label>
            <div
              className={styles.colorSelectIcon}
              style={{ backgroundColor: fill }}
              onClick={() => setShowPicker((v) => !v)}
            />
            {showPicker && (
              <div className={styles.colorPickerPopover} ref={pickerRef}>
                <SketchPicker
                  color={fill}
                  onChangeComplete={(c) => {
                    setFill(c.hex);
                    setShowPicker(false);
                  }}
                />
              </div>
            )}
          </div>

          <div className={styles.formGroup}>
            <label>Density:</label>
            <input
              type="range"
              min={0.25}
              max={5}
              step={0.25}
              value={density}
              onChange={(e) => setDensity(+e.target.value)}
            />
            <span className={styles.valueBox}>{density}</span>
          </div>

          <div className={styles.formGroup}>
            <label>Block Size:</label>
            <input
              type="range"
              min={4}
              max={64}
              step={1}
              value={blockSize}
              onChange={(e) => setBlockSize(+e.target.value)}
            />
            <span className={styles.valueBox}>{blockSize}</span>
          </div>
        </div>
      </div>

      <div className={styles.mainContainer}>
        <div className={styles.imagesContainer}>
          {fileURL && (
            <div className={styles.imageBox}>
              <img src={fileURL} alt="uploaded" />
            </div>
          )}
          <div className={styles.imageBox}>
            <canvas ref={canvasRef} />
          </div>
        </div>
      </div>
    </>
  );
}
